const cfg = $('Config').first().json;
const resp = $('L1 Get Expenses (QuickBooks)').first().json;
const all = (resp.QueryResponse && resp.QueryResponse.Purchase) || [];
const existing = new Set();
for (const page of $input.all()) for (const r of (page.json.records || [])) if (r.fields && r.fields['QuickBooks ID']) existing.add(String(r.fields['QuickBooks ID']));
const H = String(cfg.holdingAccountId);
const isExpense = p => p.Credit !== true;
const amt = p => Number(p.TotalAmt || 0).toFixed(2);
const dupKey = p => p.EntityRef ? p.EntityRef.value + '|' + amt(p) + '|' + p.TxnDate : null;
const groups = {};
all.filter(isExpense).forEach(p => { const k = dupKey(p); if (k) (groups[k] = groups[k] || []).push(String(p.Id)); });
const expLines = p => (p.Line || []).filter(l => l.DetailType === 'AccountBasedExpenseLineDetail' && l.AccountBasedExpenseLineDetail);
const holding = all.filter(p => isExpense(p) && expLines(p).some(l => String(l.AccountBasedExpenseLineDetail.AccountRef.value) === H));
const now = new Date().toISOString();
const abbr = { 'Potential Duplicate': 'DUP', 'Missing Vendor': 'NOVEN', 'Missing Description': 'NODESC', 'Large Amount': 'LARGE', 'Multiple Lines': 'MULTI' };
const reviews = [], exceptions = [];
let alreadyLogged = 0;
for (const p of holding) {
  const id = String(p.Id);
  if (existing.has(id)) { alreadyLogged++; continue; }
  const lines = expLines(p);
  const desc = lines.map(l => l.Description).filter(Boolean).join(' | ');
  const vendor = p.EntityRef ? p.EntityRef.name : '';
  const ex = [];
  const k = dupKey(p);
  const others = k ? groups[k].filter(x => x !== id) : [];
  if (others.length) ex.push(['Potential Duplicate', 'Medium', 'Same vendor, amount and date as QuickBooks expense ' + others.join(', ') + '. Requires review. Do not delete or reverse automatically.', others.join(', ')]);
  if (!vendor) ex.push(['Missing Vendor', 'Medium', 'No vendor is recorded on this expense.', '']);
  if (!desc) ex.push(['Missing Description', 'Low', 'No description is recorded on this expense.', '']);
  if (Number(p.TotalAmt) >= cfg.largeAmountThreshold) ex.push(['Large Amount', Number(p.TotalAmt) >= cfg.highSeverityAmount ? 'High' : 'Medium', 'Amount is at or above the configured review threshold of $' + cfg.largeAmountThreshold + '.', '']);
  if (lines.length > 1) ex.push(['Multiple Lines', 'Low', 'Expense has ' + lines.length + ' lines. Review each line manually.', '']);
  const flags = ex.map(e => e[0]);
  reviews.push({ fields: {
    'Transaction Key': 'QB-' + id, 'QuickBooks ID': id, 'Sync Token': String(p.SyncToken), 'Txn Date': p.TxnDate,
    'Vendor': vendor, 'Vendor ID': p.EntityRef ? String(p.EntityRef.value) : '', 'Amount': Number(p.TotalAmt), 'Description': desc,
    'Payment Account': p.AccountRef ? p.AccountRef.name : '', 'Current Category': lines[0] ? lines[0].AccountBasedExpenseLineDetail.AccountRef.name : '',
    'Exception Flags': flags, 'Review Status': 'New', 'Processing Date': now
  }});
  ex.forEach(e => exceptions.push({ fields: {
    'Exception Key': abbr[e[0]] + '-QB-' + id, 'Type': e[0], 'QuickBooks ID': id, 'Related IDs': e[3],
    'Description': (vendor || '(no vendor)') + ' | $' + amt(p) + ' | ' + p.TxnDate + '. ' + e[2],
    'Severity': e[1], 'Detected Date': now, 'Status': 'Open'
  }}));
}
const summary = { purchasesRead: all.length, inHoldingAccount: holding.length, alreadyInReviewQueue: alreadyLogged, newForReview: reviews.length, newWithFlags: reviews.filter(r => r.fields['Exception Flags'].length).length, exceptionRecords: exceptions.length };
return [{ json: { reviews, exceptions, summary } }];

const cfg = $('Config').first().json;
const acc = (($('L1b Get Expense Accounts (QuickBooks)').first().json.QueryResponse) || {}).Account || [];
const exclude = new Set(cfg.excludeAccountIds.map(String));
const allowed = {};
acc.filter(a => a.Active && !exclude.has(String(a.Id))).forEach(a => { allowed[String(a.Id)] = a.FullyQualifiedName; });
const nameToId = {};
Object.keys(allowed).forEach(id => { nameToId[allowed[id].toLowerCase()] = id; });
// Vendor history = categories this firm's review process already approved for the vendor
const hist = {};
for (const page of $('L1b Get Approved History (Airtable)').all()) {
  for (const r of (page.json.records || [])) {
    const f = r.fields || {};
    const vid = f['Vendor ID'];
    if (!vid) continue;
    const cid = f['Reviewer Category'] ? (nameToId[String(f['Reviewer Category']).toLowerCase()] || null) : (f['Suggested Category ID'] || null);
    if (!cid) continue;
    (hist[vid] = hist[vid] || []);
    if (!hist[vid].includes(String(cid))) hist[vid].push(String(cid));
  }
}
const recs = [];
for (const page of $input.all()) for (const r of (page.json.records || [])) recs.push(r);
const list = recs.slice(0, cfg.maxItemsPerRun);
const catList = Object.keys(allowed).map(id => id + ' | ' + allowed[id]).join('\n');
const system = [
  'You are Jev, an AI assistant that helps a bookkeeping team categorize business expenses in QuickBooks Online. You only make recommendations; the firm\'s rules and a person make the final decision.',
  'Choose exactly ONE category from the ALLOWED CATEGORIES list and return its id. Never invent a category.',
  'Confidence (0-100) must reflect how certain the category is from the information given:',
  '- 95-100: vendor and description clearly and unambiguously point to one category.',
  '- 80-94: likely, but another category could reasonably apply.',
  '- below 80: unclear, generic or missing information (no vendor, no description, vague description, unfamiliar vendor).',
  'Be conservative. Large or unusual amounts with vague descriptions deserve lower confidence. If a purchase may need to be recorded as a fixed asset instead of an expense, say so in concerns and lower confidence.',
  'Never make accusations and never use the word fraud. Describe concerns neutrally, for example "requires review".',
  'Reply with ONLY a JSON object and no other text, in this exact shape:',
  '{"categoryId":"<id>","categoryName":"<name>","confidence":<integer 0-100>,"reasoning":"<at most 2 short sentences>","concerns":["<short concern>"]}'
].join('\n');
return list.map(r => {
  const f = r.fields || {};
  const flags = f['Exception Flags'] || [];
  const user = 'TRANSACTION (Fictional / Sample Data)\n' +
    'Vendor: ' + (f['Vendor'] || '(none recorded)') + '\n' +
    'Amount: $' + Number(f['Amount'] || 0).toFixed(2) + '\n' +
    'Date: ' + (f['Txn Date'] || '') + '\n' +
    'Description: ' + (f['Description'] || '(none recorded)') + '\n' +
    'Paid from: ' + (f['Payment Account'] || '') + '\n' +
    'Rule-based flags already raised: ' + (flags.length ? flags.join(', ') : 'none') + '\n\n' +
    'ALLOWED CATEGORIES (id | name):\n' + catList;
  return { json: {
    recId: r.id, qbId: f['QuickBooks ID'], vendor: f['Vendor'] || '', vendorId: f['Vendor ID'] || '',
    amount: Number(f['Amount'] || 0), flags, history: hist[f['Vendor ID']] || [], allowed,
    body: { model: cfg.model, temperature: 0, max_tokens: 400, messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] }
  } };
});

const cfg = $('Config').first().json;
const prep = $('L1b Prepare Prompts').all();
const res = $input.all();
const BT = String.fromCharCode(96);
const now = new Date().toISOString();
const updates = [], exceptions = [], lines = [];
const counts = { autoApproved: 0, reviewRequired: 0, exception: 0, aiUnavailable: 0, lowConfidence: 0 };
for (let i = 0; i < prep.length; i++) {
  const p = prep[i].json;
  const r = (res[i] && res[i].json) || {};
  let ai = null, aiErr = null;
  try {
    const c = r.choices[0].message.content;
    const t = c.split(BT + BT + BT + 'json').join('').split(BT + BT + BT).join('').trim();
    ai = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  } catch (e) {
    aiErr = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || 'AI request failed')) : 'AI response missing or unreadable';
  }
  if (ai) {
    const id = String(ai.categoryId);
    const conf = Number(ai.confidence);
    if (!p.allowed[id]) { aiErr = 'AI suggested a category that is not in the allowed list (' + id + ')'; ai = null; }
    else if (!Number.isFinite(conf) || conf < 0 || conf > 100) { aiErr = 'AI returned an invalid confidence value'; ai = null; }
    else { ai.categoryId = id; ai.categoryName = p.allowed[id]; ai.confidence = Math.round(conf); }
  }
  const f = {};
  let decision, status, rule;
  if (!ai) {
    counts.aiUnavailable++;
    decision = 'Review Required'; status = 'Pending Review';
    rule = 'AI unavailable - routed to human review. Reason: ' + String(aiErr).slice(0, 200);
    f['AI Reasoning'] = 'No AI recommendation. ' + String(aiErr).slice(0, 300);
  } else {
    const gConf = ai.confidence >= cfg.autoApproveMinConfidence;
    const gHist = p.history.includes(ai.categoryId);
    const gAmt = p.amount < cfg.autoApproveMaxAmount;
    const gFlags = p.flags.length === 0;
    rule = 'Confidence ' + ai.confidence + ' (min ' + cfg.autoApproveMinConfidence + '): ' + (gConf ? 'pass' : 'fail') +
      ' | Vendor previously approved with this category: ' + (gHist ? 'pass' : 'fail') +
      ' | Amount under $' + cfg.autoApproveMaxAmount + ': ' + (gAmt ? 'pass' : 'fail') +
      ' | No exception flags: ' + (gFlags ? 'pass' : 'fail');
    if (!gFlags) { decision = 'Exception'; counts.exception++; }
    else if (gConf && gHist && gAmt) { decision = 'Auto-Approved'; counts.autoApproved++; }
    else { decision = 'Review Required'; counts.reviewRequired++; }
    status = decision === 'Auto-Approved' ? 'Approved' : 'Pending Review';
    rule += ' => ' + decision;
    f['Suggested Category'] = ai.categoryName;
    f['Suggested Category ID'] = ai.categoryId;
    f['Confidence'] = ai.confidence;
    const concerns = Array.isArray(ai.concerns) ? ai.concerns.filter(Boolean) : [];
    f['AI Reasoning'] = String(ai.reasoning || '').slice(0, 600) + (concerns.length ? ' Concerns: ' + concerns.join('; ').slice(0, 400) : '');
    if (decision === 'Auto-Approved') f['Reviewer'] = 'System rule (auto-approval gate)';
    if (ai.confidence < cfg.reviewThreshold) {
      counts.lowConfidence++;
      exceptions.push({ fields: { 'Exception Key': 'LOWCONF-QB-' + p.qbId, 'Type': 'Low Confidence', 'QuickBooks ID': String(p.qbId), 'Related IDs': '',
        'Description': (p.vendor || '(no vendor)') + ' | $' + p.amount.toFixed(2) + '. AI confidence ' + ai.confidence + ' is below ' + cfg.reviewThreshold + '. Manual review required.',
        'Severity': 'Medium', 'Detected Date': now, 'Status': 'Open' } });
    }
  }
  f['Decision'] = decision; f['Review Status'] = status; f['Rule Applied'] = rule;
  updates.push({ id: p.recId, fields: f });
  lines.push('QB-' + p.qbId + ': ' + (ai ? ai.categoryName + ' (' + ai.confidence + ')' : 'no AI') + ' -> ' + decision);
}
const summary = { model: cfg.model, processed: prep.length, counts, items: lines };
return [{ json: { updates, exceptions, summary } }];

const cfg = $('Config').first().json;
const s = $input.first().json.summary;
if (!s.counts.aiUnavailable) return [];
const failed = s.items.filter(x => x.indexOf('no AI') !== -1).join('
');
return [{ json: { alertEmail: cfg.alertEmail, subject: '[QBAI ALERT] Jev unavailable for ' + s.counts.aiUnavailable + ' of ' + s.processed + ' items', body: 'Jev (AI) could not review ' + s.counts.aiUnavailable + ' of ' + s.processed + ' items in execution ' + $execution.id + '.
These items were routed to human review in Airtable (Review Status = Pending Review, Rule Applied starts with "AI unavailable").

Items:
' + failed + '

Check: OpenRouter key and credit limit, model name in Config, OpenRouter status. No QuickBooks data was changed.' } }];

const cfg = $('Config').first().json;
const acc = (($('L2 Get Expense Accounts (QuickBooks)').first().json.QueryResponse) || {}).Account || [];
const allowed = {};
acc.filter(a => a.Active && !cfg.excludeAccountIds.includes(String(a.Id))).forEach(a => { allowed[String(a.Id)] = a.FullyQualifiedName; });
const nameToId = {};
Object.keys(allowed).forEach(id => { nameToId[allowed[id].toLowerCase()] = id; });
const recs = [];
for (const page of $input.all()) for (const r of (page.json.records || [])) recs.push(r);
return recs.slice(0, cfg.maxItemsPerRun).map(r => {
  const f = r.fields || {};
  const status = f['Review Status'];
  let targetId = null, reason = null;
  const revCat = f['Reviewer Category'] ? String(f['Reviewer Category']) : '';
  if (!f['QuickBooks ID']) reason = 'Missing QuickBooks ID on the review record.';
  else if (status === 'Changed') {
    if (!revCat) reason = 'Review Status is Changed but Reviewer Category is empty. Pick a category or set Approved.';
    else { targetId = nameToId[revCat.toLowerCase()] || null; if (!targetId) reason = 'Reviewer Category "' + revCat + '" is not an active QuickBooks expense account.'; }
  } else if (status === 'Approved') {
    if (revCat) reason = 'Reviewer Category is filled but Review Status is Approved. Set Changed to use your category, or clear Reviewer Category to use the AI suggestion.';
    else if (!f['Suggested Category ID']) reason = 'Approved but there is no AI suggestion. Pick a Reviewer Category and set Changed.';
    else { targetId = String(f['Suggested Category ID']); if (!allowed[targetId]) reason = 'Suggested category is no longer an active QuickBooks expense account.'; }
  } else reason = 'Unexpected Review Status: ' + status;
  return { json: {
    recId: r.id, qbId: String(f['QuickBooks ID'] || ''), status, decision: f['Decision'] || '', reviewer: f['Reviewer'] || '',
    notes: f['Reviewer Notes'] || '', amount: Number(f['Amount'] || 0), targetId, targetName: targetId ? allowed[targetId] : null,
    valid: !reason, reason, holdingId: String(cfg.holdingAccountId), qbBase: cfg.qbBase
  } };
});

const p = $('L2 Plan Updates').item.json;
const r = $json.Purchase || {};
const lines = r.Line || [];
const H = p.holdingId;
const isHold = l => l.DetailType === 'AccountBasedExpenseLineDetail' && l.AccountBasedExpenseLineDetail && String(l.AccountBasedExpenseLineDetail.AccountRef.value) === H;
let reason = null;
if (!r.Id) reason = 'QuickBooks did not return the expense.';
else if (r.Credit === true) reason = 'This is a credit, not an expense. Update manually in QuickBooks.';
else if (!lines.some(isHold)) reason = 'Expense is no longer in the holding account in QuickBooks (already categorized by someone?). No change made.';
else if (lines.length > 1) reason = 'Expense has ' + lines.length + ' lines. Multi-line expenses are updated manually in QuickBooks.';
else if (Number(r.TotalAmt).toFixed(2) !== Number(p.amount).toFixed(2)) reason = 'Amount changed in QuickBooks since review ($' + Number(p.amount).toFixed(2) + ' reviewed, $' + Number(r.TotalAmt).toFixed(2) + ' now). Re-review required.';
if (reason) return { json: { safe: false, reason } };
const newLines = lines.map(l => {
  const c = JSON.parse(JSON.stringify(l));
  delete c.CustomExtensions;
  if (isHold(c)) c.AccountBasedExpenseLineDetail.AccountRef = { value: p.targetId };
  return c;
});
const body = { Id: r.Id, SyncToken: r.SyncToken, sparse: true, PaymentType: r.PaymentType, AccountRef: { value: r.AccountRef.value }, Line: newLines };
return { json: { safe: true, oldSyncToken: r.SyncToken, oldCategory: 'Uncategorized Expense', body } };

const p = $('L2 Plan Updates').item.json;
const b = $('L2 Check & Build Update').item.json;
const r = $json.Purchase || {};
const now = new Date().toISOString();
const newCat = (r.Line && r.Line[0] && r.Line[0].AccountBasedExpenseLineDetail) ? r.Line[0].AccountBasedExpenseLineDetail.AccountRef.name : p.targetName;
return { json: { ok: true, recId: p.recId, qbId: p.qbId,
  fields: { 'Review Status': 'Synced', 'Synced At': now, 'Sync Token': String(r.SyncToken), 'Current Category': newCat },
  audit: { 'Event ID': 'QBU-' + p.qbId + '-' + $execution.id, 'Timestamp': now, 'Workflow': $('Config').first().json.workflowName, 'Event Type': 'QuickBooks Update', 'Status': 'Success', 'QuickBooks ID': p.qbId,
    'Details': 'Expense QB-' + p.qbId + ' re-categorized: ' + b.oldCategory + ' -> ' + newCat + ' (account ' + p.targetId + '). Basis: ' + p.status + ' by ' + (p.reviewer || 'unknown') + (p.decision ? ' (Decision: ' + p.decision + ')' : '') + '. SyncToken ' + b.oldSyncToken + ' -> ' + r.SyncToken + '.' } } };

const p = $('L2 Plan Updates').item.json;
const e = $json.error;
let reason = $json.reason || (e ? ((e.message || '') + (e.description ? ' - ' + e.description : '')) : 'Unknown error');
reason = String(reason).split(',"isAxiosError"')[0].split('"headers"')[0].replace(/Bearer\s+[A-Za-z0-9._\-]+/g, 'Bearer [redacted]').slice(0, 500);
const now = new Date().toISOString();
const stamp = now.slice(0, 16).replace('T', ' ');
return { json: { ok: false, recId: p.recId, qbId: p.qbId, reason,
  fields: { 'Review Status': 'Sync Failed', 'Reviewer Notes': (p.notes ? p.notes + '\n' : '') + '[Sync failed ' + stamp + ' UTC] ' + reason },
  audit: { 'Event ID': 'QBU-' + p.qbId + '-' + $execution.id, 'Timestamp': now, 'Workflow': $('Config').first().json.workflowName, 'Event Type': 'QuickBooks Update', 'Status': 'Failed', 'QuickBooks ID': p.qbId,
    'Details': 'Expense QB-' + p.qbId + ' NOT updated. Reason: ' + reason + ' Basis: ' + p.status + ' by ' + (p.reviewer || 'unknown') + '.' } } };

const items = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < items.length; i += 10) {
  const chunk = items.slice(i, i + 10);
  out.push({ json: {
    reviewPayload: { typecast: true, records: chunk.map(x => ({ id: x.recId, fields: x.fields })) },
    auditPayload: { typecast: true, records: chunk.map(x => ({ fields: x.audit })) },
    failures: chunk.filter(x => !x.ok).map(x => 'QB-' + x.qbId + ': ' + x.reason),
    synced: chunk.filter(x => x.ok).map(x => 'QB-' + x.qbId)
  } });
}
return out;

const cfg = $('Config').first().json;
const f = $input.all().flatMap(i => i.json.failures || []);
if (!f.length) return [];
return [{ json: { alertEmail: cfg.alertEmail, subject: '[QBAI ALERT] ' + f.length + ' approved item(s) could not be updated in QuickBooks', body: 'The approval sync could not update these expenses in QuickBooks (execution ' + $execution.id + '):

' + f.join('
') + '

They are marked "Sync Failed" in Airtable (view: 2. Approved - waiting for QuickBooks) with the reason in Reviewer Notes. Fix the cause, then set Review Status back to Approved or Changed. They will be retried on the next run.' } }];

const cfg = $('Config').first().json;
const stage = cfg.laneLabel;
const msgs = $input.all().map(i => { const e = i.json.error || i.json; let m = (e.message || '') + (e.description ? ' - ' + e.description : '') + (e.httpCode ? ' (HTTP ' + e.httpCode + ')' : ''); if (!m) m = JSON.stringify(e); m = m.split(',"isAxiosError"')[0].split('"headers"')[0]; return m.slice(0, 600); });
const clean = msgs.join('
').replace(/Bearer\s+[A-Za-z0-9._\-]+/g, 'Bearer [redacted]').replace(/(token|secret|key)=[^&\s]+/gi, '$1=[redacted]').replace(/set-cookie[^
]*/gi, '[redacted]').slice(0, 2000);
const subject = '[QBAI ALERT] ' + stage + ' - a step failed';
const body = 'Lane: ' + stage + '
Workflow: ' + cfg.workflowName + '
Execution ID: ' + $execution.id + '
Time (UTC): ' + new Date().toISOString() + '
Failed items: ' + $input.all().length + '

Error:
' + clean + '

What happens next: QuickBooks remains the source of truth. Items that were not processed keep their status and are picked up on the next run; the approval sync re-checks each expense before changing it, so nothing is updated twice. Check this execution in n8n, fix the cause, then re-run the lane.';
return [{ json: { subject, body, alertEmail: cfg.alertEmail, payload: { typecast: true, records: [{ fields: { 'Event ID': 'ERR-' + $execution.id + '-' + cfg.lane, 'Timestamp': new Date().toISOString(), 'Workflow': cfg.workflowName, 'Event Type': 'Error', 'Status': 'Failed', 'Details': body } }] } } }];

// Lane 4: runs only when a LIVE (scheduled) execution of this workflow crashes unexpectedly.
const e = $json.execution || {};
const err = e.error || {};
let msg = String((err.message || '') + (err.description ? ' - ' + err.description : '')).split(',"isAxiosError"')[0].split('"headers"')[0];
msg = msg.replace(/Bearer\s+[A-Za-z0-9._\-]+/g, 'Bearer [redacted]').slice(0, 1500);
return [{ json: { alertEmail: 'alerts@example.com', subject: '[QBAI ALERT] Workflow crashed - ' + (($json.workflow || {}).name || 'QBAI'), body: 'An unexpected error stopped a live run.

Workflow: ' + (($json.workflow || {}).name || '') + '
Execution ID: ' + (e.id || '') + '
Last node: ' + (e.lastNodeExecuted || '') + '
Mode: ' + (e.mode || '') + '

Error:
' + msg + '

QuickBooks remains the source of truth; unprocessed items are retried on the next scheduled run. Open the execution in n8n to investigate.' } }];

const cfg = $('Config').first().json;
const files = ($('L3 List Receipt Files (Drive)').first().json.files) || [];
const reviews = [];
for (const p of $('L3 Get Receipt Candidates (Airtable)').all()) for (const r of (p.json.records || [])) reviews.push(r);
const reqs = [];
for (const p of $input.all()) for (const r of (p.json.records || [])) reqs.push(r);
const findFile = qb => files.find(f => new RegExp('(^|[^0-9A-Za-z])QB-' + qb + '(?![0-9])', 'i').test(f.name || ''));
const reqByQb = {};
reqs.forEach(r => { const q = String((r.fields || {})['QuickBooks ID'] || ''); if (q) reqByQb[q] = r; });
const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);
const note = (old, txt) => (old ? old + '\n' : '') + '[' + today + '] ' + txt;
const reviewUpdates = [], newRequests = [], requestUpdates = [], toSend = [], received = [], escalated = [];
const counts = { candidates: reviews.length, notRequired: 0, found: 0, missing: 0, newRequests: 0, toSend: 0, received: 0, escalated: 0, blocked: 0 };
// 1. Transaction Review: decide receipt status
for (const r of reviews) {
  const f = r.fields || {};
  const qb = String(f['QuickBooks ID'] || '');
  if (!qb) continue;
  const amt = Number(f['Amount'] || 0);
  if (amt < cfg.receiptThreshold) { reviewUpdates.push({ id: r.id, fields: { 'Receipt Status': 'Not Required' } }); counts.notRequired++; continue; }
  const file = findFile(qb);
  if (file) { reviewUpdates.push({ id: r.id, fields: { 'Receipt Status': 'Found', 'Receipt URL': file.webViewLink || '' } }); counts.found++; continue; }
  counts.missing++;
  if (f['Receipt Status'] !== 'Missing') reviewUpdates.push({ id: r.id, fields: { 'Receipt Status': 'Missing' } });
  if (!reqByQb[qb]) { newRequests.push({ qbId: qb, vendor: f['Vendor'] || '', amount: amt, txnDate: f['Txn Date'] || '', description: f['Description'] || '' }); counts.newRequests++; }
}
// 2. Document Requests: received, send approved, escalate overdue
const open = ['Pending Approval', 'Approved to Send', 'Requested', 'Waiting for Client', 'Escalated', 'Send Failed'];
for (const r of reqs) {
  const f = r.fields || {};
  const qb = String(f['QuickBooks ID'] || '');
  const st = f['Status'];
  if (!open.includes(st)) continue;
  const file = findFile(qb);
  if (file) {
    requestUpdates.push({ id: r.id, fields: { 'Status': 'Received', 'Received Date': nowIso, 'Document URL': file.webViewLink || '', 'Notes': note(f['Notes'], 'Receipt found in Drive: ' + file.name + '. Check it, then set Status to Verified.') } });
    received.push('QB-' + qb + ' ' + (f['Vendor'] || '(no vendor)') + ' $' + Number(f['Amount'] || 0).toFixed(2)); counts.received++;
    continue;
  }
  if (st === 'Approved to Send') {
    if (!f['Draft Subject'] || !f['Draft Body']) {
      requestUpdates.push({ id: r.id, fields: { 'Status': 'Pending Approval', 'Notes': note(f['Notes'], 'Not sent: Draft Subject or Draft Body is empty.') } }); counts.blocked++;
    } else {
      const to = cfg.testMode ? cfg.testRecipient : (f['Recipient Email'] || cfg.clientContactEmail);
