const aud = rows('L6 Get Recent Audit Log (Airtable)');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' });
const startMs = Date.parse(today + 'T00:00:00+08:00') - 6 * 86400000;
const start = new Date(startMs + 8 * 3600000).toISOString().slice(0, 10);
const inWeek = d => d && Date.parse(d) >= startMs;
const cnt = (a, f) => a.filter(f).length;
const by = (a, k) => a.reduce((m, x) => { const v = x[k] || '(blank)'; m[v] = (m[v] || 0) + 1; return m; }, {});
const sum = (a, k) => Math.round(a.reduce((s, x) => s + Number(x[k] || 0), 0) * 100) / 100;
const daysAgo = d => Math.floor((Date.now() - Date.parse(d)) / 86400000);
// Expenses
const expenses = {
  newThisWeek: cnt(rev, r => inWeek(r['Processing Date'])),
  waitingForReview: cnt(rev, r => ['New', 'Pending Review'].includes(r['Review Status'])),
  approvedWaitingForQuickBooks: cnt(rev, r => ['Approved', 'Changed'].includes(r['Review Status'])),
  syncFailed: cnt(rev, r => r['Review Status'] === 'Sync Failed'),
  rejected: cnt(rev, r => r['Review Status'] === 'Rejected'),
  updatedInQuickBooksThisWeek: cnt(aud, a => a['Event Type'] === 'QuickBooks Update' && a['Status'] === 'Success'),
  autoApprovedAllTime: cnt(rev, r => r['Decision'] === 'Auto-Approved'),
  totalTracked: rev.length
};
// Exceptions
const openExc = exc.filter(e => e['Status'] === 'Open');
const oldest = openExc.filter(e => e['Detected Date']).sort((a, b) => Date.parse(a['Detected Date']) - Date.parse(b['Detected Date']))[0];
const exceptions = { open: openExc.length, openBySeverity: by(openExc, 'Severity'), openByType: by(openExc, 'Type'), newThisWeek: cnt(exc, e => inWeek(e['Detected Date'])), oldestOpenDays: oldest ? daysAgo(oldest['Detected Date']) : 0 };
// Receipts
const receipts = { missing: cnt(rev, r => r['Receipt Status'] === 'Missing' && r['Review Status'] !== 'Rejected'), requestsByStatus: by(doc, 'Status'), requestsSentThisWeek: cnt(aud, a => a['Event Type'] === 'Document Request' && a['Status'] === 'Success') };
// Invoices
const openInv = inv.filter(i => !['Paid / Closed', 'Cancelled'].includes(i['Status']));
const invoices = { trackedOpen: openInv.length, openBalance: sum(openInv, 'Open Balance'), byAgingBucket: by(openInv, 'Aging Bucket'), byStatus: by(openInv, 'Status'),
  remindersSentThisWeek: cnt(aud, a => a['Event Type'] === 'Invoice Reminder' && a['Status'] === 'Success'),
  closedThisWeek: cnt(inv, i => i['Status'] === 'Paid / Closed' && inWeek(i['Last Checked'])),
  escalated: openInv.filter(i => i['Status'] === 'Escalated').map(i => 'Invoice ' + i['Invoice No.'] + ' ' + (i['Customer'] || '') + ' $' + Number(i['Open Balance'] || 0).toFixed(2) + ' (' + (i['Days Overdue'] || 0) + ' days)') };
// System health
const health = { errorsThisWeek: cnt(aud, a => a['Event Type'] === 'Error'), emailSendFailuresThisWeek: cnt(aud, a => ['Document Request', 'Invoice Reminder'].includes(a['Event Type']) && a['Status'] === 'Failed'), updatesRefusedBySafetyCheckThisWeek: cnt(aud, a => a['Event Type'] === 'QuickBooks Update' && a['Status'] === 'Failed'), runsLogged: by(aud.filter(a => ['Intake Run', 'AI Review', 'Receipt Check', 'Invoice Check'].includes(a['Event Type'])), 'Event Type') };
// Actions for people
const actions = [];
if (expenses.waitingForReview) actions.push(expenses.waitingForReview + ' expense(s) waiting for review (Airtable: 1. Review Queue).');
if (expenses.syncFailed) actions.push(expenses.syncFailed + ' expense(s) could not be updated in QuickBooks (Review Status = Sync Failed).');
if (exceptions.open) actions.push(exceptions.open + ' open exception(s) (Airtable: Open Exceptions)' + (exceptions.openBySeverity.High ? ', ' + exceptions.openBySeverity.High + ' high severity' : '') + '.');
const docPend = (receipts.requestsByStatus['Pending Approval'] || 0), docEsc = (receipts.requestsByStatus['Escalated'] || 0), docRec = (receipts.requestsByStatus['Received'] || 0);
if (docPend) actions.push(docPend + ' receipt request draft(s) to approve or cancel.');
if (docRec) actions.push(docRec + ' received receipt(s) to check and mark Verified.');
if (docEsc) actions.push(docEsc + ' escalated receipt request(s) need a decision.');
const invPend = invoices.byStatus['Pending Approval'] || 0;
if (invPend) actions.push(invPend + ' invoice reminder draft(s) to approve, hold or cancel.');
if (invoices.escalated.length) actions.push(invoices.escalated.length + ' escalated overdue invoice(s) need a decision (call, payment plan, or On Hold).');
if (health.errorsThisWeek) actions.push(health.errorsThisWeek + ' system error(s) logged this week - check the Audit Log.');
if (health.emailSendFailuresThisWeek) actions.push(health.emailSendFailuresThisWeek + ' email(s) could not be sent this week (Status = Send Failed).');
if (health.updatesRefusedBySafetyCheckThisWeek) actions.push(health.updatesRefusedBySafetyCheckThisWeek + ' QuickBooks update(s) were refused by the safety check - see the Audit Log.');
const metrics = { period: { start, end: today }, client: cfg.clientName, expenses, exceptions, receipts, invoices, health, actions };
const system = 'You are Jev, an assistant to a bookkeeping team. Write a short weekly summary for the team lead from the metrics JSON. Plain text, no markdown, 3 to 5 sentences, then the line "Top priorities:" followed by up to 3 lines starting with "- ". Use ONLY numbers that appear in the JSON; do not calculate new figures, estimate time saved, judge accuracy, or invent causes. If a value is 0, you may say so briefly. Do not describe or guess the cause of errors or failures; just state the count and that details are in the Audit Log. Do not explain why any item was escalated, flagged or overdue. Neutral, professional tone.';
return [{ json: { metrics, body: { model: cfg.model, temperature: 0.2, max_tokens: 500, messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(metrics) }] } } }];

const cfg = $('Config').first().json;
const m = $('L6 Build Weekly Metrics').first().json.metrics;
const r = $input.first().json || {};
let summary = '', source = 'Jev';
try { summary = String(r.choices[0].message.content || '').trim(); } catch (e) { summary = ''; }
if (!summary) { source = 'none'; summary = 'AI summary unavailable this week. The figures below are complete.'; }
const esc = s => String(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const money = n => '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e7eb"';
const row = (k, v) => '<tr><td ' + td + '>' + esc(k) + '</td><td ' + td + ' align="right"><b>' + esc(v) + '</b></td></tr>';
const table = (title, rows) => '<h3 style="margin:22px 0 6px;font-size:15px;color:#111827">' + esc(title) + '</h3><table cellspacing="0" style="border-collapse:collapse;width:100%;max-width:560px;font-size:14px">' + rows.join('') + '</table>';
const obj = o => Object.keys(o).length ? Object.keys(o).map(k => k + ': ' + o[k]).join(', ') : 'none';
const e = m.expenses, x = m.exceptions, rc = m.receipts, iv = m.invoices, h = m.health;
const html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;max-width:600px">' +
  '<p style="font-size:12px;color:#b45309;margin:0 0 8px">FICTIONAL / SAMPLE DATA - portfolio demonstration</p>' +
  '<h2 style="margin:0;font-size:20px">Weekly Bookkeeping Report</h2>' +
  '<p style="margin:4px 0 16px;color:#6b7280">' + esc(m.client) + ' | ' + m.period.start + ' to ' + m.period.end + '</p>' +
  '<div style="background:#f3f4f6;padding:12px 14px;border-radius:6px;white-space:pre-wrap;font-size:14px">' + esc(summary) + '</div>' +
  (m.actions.length ? '<h3 style="margin:22px 0 6px;font-size:15px">Needs a person</h3><ul style="margin:0;padding-left:18px;font-size:14px">' + m.actions.map(a => '<li>' + esc(a) + '</li>').join('') + '</ul>' : '<p>Nothing is waiting for a person this week.</p>') +
  table('Expenses', [row('New expenses this week', e.newThisWeek), row('Waiting for review', e.waitingForReview), row('Approved, waiting for QuickBooks update', e.approvedWaitingForQuickBooks), row('Updated in QuickBooks this week', e.updatedInQuickBooksThisWeek), row('Could not update (Sync Failed)', e.syncFailed), row('Auto-approved (all time)', e.autoApprovedAllTime)]) +
  table('Exceptions', [row('Open', x.open), row('Open by severity', obj(x.openBySeverity)), row('New this week', x.newThisWeek), row('Oldest open (days)', x.oldestOpenDays)]) +
  table('Receipts', [row('Expenses with missing receipts', rc.missing), row('Requests sent this week', rc.requestsSentThisWeek), row('Requests by status', obj(rc.requestsByStatus))]) +
  table('Overdue invoices', [row('Open overdue invoices tracked', iv.trackedOpen), row('Open balance', money(iv.openBalance)), row('By age', obj(iv.byAgingBucket)), row('Reminders sent this week', iv.remindersSentThisWeek), row('Paid / closed this week', iv.closedThisWeek)]) +
  (iv.escalated.length ? '<p style="font-size:14px"><b>Escalated invoices:</b><br>' + iv.escalated.map(esc).join('<br>') + '</p>' : '') +
  table('System health', [row('Errors logged this week', h.errorsThisWeek), row('Emails that could not be sent', h.emailSendFailuresThisWeek), row('QuickBooks updates refused by safety check', h.updatesRefusedBySafetyCheckThisWeek), row('Runs logged', obj(h.runsLogged))]) +
  '<p style="margin-top:22px;font-size:12px;color:#6b7280">Summary written by Jev (AI) from the figures above; figures come directly from Airtable. Decisions remain with the bookkeeping team.<br>QuickBooks AI Operations Assistant | Fictional / Sample Data</p></div>';
const subject = '[QBAI] Weekly Bookkeeping Report: ' + m.period.start + ' to ' + m.period.end;
return [{ json: { to: cfg.alertEmail, subject, html, log: { typecast: true, records: [{ fields: { 'Event ID': 'WEEKLY-' + $execution.id, 'Timestamp': new Date().toISOString(), 'Workflow': cfg.workflowName, 'Event Type': 'Weekly Report', 'Status': 'Success', 'Details': JSON.stringify({ summarySource: source, metrics: m }, null, 2).slice(0, 90000) } }] } } }];
